import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";

/**
 * The favicon and app icons (21 Nov 2026), all generated by
 * scripts/generate-icons.mjs from the two-message mark on the brand green.
 *
 * Before: the tab icon was a single near-black bubble from the old palette
 * and /favicon.ico — which browsers and Google request by default — was a 404.
 */

const read = (p: string) => readFileSync(join(process.cwd(), p));

describe("the favicon", () => {
  it("is an .ico holding 16, 32 and 48px PNGs", () => {
    const ico = read("app/favicon.ico");
    expect(ico.readUInt16LE(0)).toBe(0); // reserved
    expect(ico.readUInt16LE(2)).toBe(1); // type: icon
    const count = ico.readUInt16LE(4);
    const sizes: number[] = [];
    for (let i = 0; i < count; i++) {
      const entry = 6 + i * 16;
      sizes.push(ico.readUInt8(entry));
      const offset = ico.readUInt32LE(entry + 12);
      // Each image is a PNG: its 8-byte signature starts 0x89 "PNG".
      expect(ico.subarray(offset + 1, offset + 4).toString("ascii")).toBe("PNG");
    }
    expect(sizes).toEqual([16, 32, 48]);
  });

  it("the SVG tab icon is the current mark in the brand colours", () => {
    const svg = read("app/icon.svg").toString("utf8");
    expect(svg).toContain('fill="#174a33"'); // the plate, --accent in light
    expect(svg).toContain('fill="#8fd4ac"'); // the rear message
    // The two messages from components/Logo.tsx, not the old single bubble.
    expect(svg).toContain("M16 10H51");
    expect(svg).toContain("M9 19H44");
  });
});
